// LM35: OUT = 10 mV per degree Celsius.
const int SENSOR_PIN = {{OUT}};

#if defined(ESP32)
const float ADC_MAX = 4095.0;  // 12-bit ADC
const float ADC_VREF = 3.3;
#else
const float ADC_MAX = 1023.0;  // 10-bit ADC
const float ADC_VREF = 5.0;
#endif

void setup() {
  Serial.begin(115200);
}

void loop() {
  float volts = analogRead(SENSOR_PIN) * ADC_VREF / ADC_MAX;
  float celsius = volts * 100.0;
  Serial.print("Temperature: ");
  Serial.print(celsius);
  Serial.println(" C");
  delay(1000);
}
